#!/usr/bin/python3
"""Safely unpack a supplier tar archive below incoming/."""
import errno
import os
from pathlib import PurePosixPath
import shutil
import stat
import sys
import tarfile


def reject(message):
    raise ValueError(message)


def checked_members(archive):
    members = []
    paths = {}
    for member in archive.getmembers():
        raw_name = member.name
        path = PurePosixPath(raw_name)
        if path.is_absolute() or raw_name.startswith("/"):
            reject("absolute member path: {!r}".format(raw_name))
        if ".." in path.parts:
            reject("parent traversal in member path: {!r}".format(raw_name))

        parts = tuple(part for part in path.parts if part not in ("", "."))
        if not parts:
            if member.isdir():
                continue
            reject("empty member path: {!r}".format(raw_name))
        if member.issym() or member.islnk():
            reject("archive links are not permitted: {!r}".format(raw_name))
        if not (member.isdir() or member.isreg()):
            reject("unsupported member type: {!r}".format(raw_name))

        key = parts
        kind = "dir" if member.isdir() else "file"
        if key in paths:
            reject("duplicate member path: {!r}".format(raw_name))
        for length in range(1, len(parts)):
            prefix = parts[:length]
            if paths.get(prefix) == "file":
                reject("member descends through a file: {!r}".format(raw_name))
        if kind == "file":
            for prior in paths:
                if len(prior) > len(parts) and prior[:len(parts)] == parts:
                    reject("file replaces an archive directory: {!r}".format(raw_name))
        paths[key] = kind
        members.append((member, parts))
    return members


def preflight_destination(destination, members):
    try:
        info = os.lstat(destination)
    except FileNotFoundError:
        return
    if stat.S_ISLNK(info.st_mode) or not stat.S_ISDIR(info.st_mode):
        reject("incoming is not a real directory")

    for member, parts in members:
        current = destination
        for index, part in enumerate(parts):
            current = os.path.join(current, part)
            try:
                info = os.lstat(current)
            except FileNotFoundError:
                break
            if stat.S_ISLNK(info.st_mode):
                reject("destination path contains a symlink: {!r}".format(member.name))
            final = index == len(parts) - 1
            if not final and not stat.S_ISDIR(info.st_mode):
                reject("destination parent is not a directory: {!r}".format(member.name))
            if final:
                if member.isdir() and not stat.S_ISDIR(info.st_mode):
                    reject("destination directory conflicts with a file: {!r}".format(member.name))
                if member.isreg():
                    reject("destination file already exists: {!r}".format(member.name))


def open_directory(parent_fd, name):
    try:
        os.mkdir(name, 0o755, dir_fd=parent_fd)
    except FileExistsError:
        pass
    return os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW,
                   dir_fd=parent_fd)


def parent_fd(root_fd, parts):
    descriptor = os.dup(root_fd)
    try:
        for part in parts:
            next_descriptor = open_directory(descriptor, part)
            os.close(descriptor)
            descriptor = next_descriptor
        return descriptor
    except Exception:
        os.close(descriptor)
        raise


def extract_checked(archive, destination, members):
    os.makedirs(destination, mode=0o755, exist_ok=True)
    root_fd = os.open(destination,
                      os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        for member, parts in members:
            if member.isdir():
                directory_fd = parent_fd(root_fd, parts)
                os.close(directory_fd)
                continue

            directory_fd = parent_fd(root_fd, parts[:-1])
            try:
                flags = (os.O_WRONLY | os.O_CREAT | os.O_EXCL |
                         os.O_NOFOLLOW)
                file_fd = os.open(parts[-1], flags, 0o600,
                                  dir_fd=directory_fd)
                try:
                    source = archive.extractfile(member)
                    if source is None:
                        raise tarfile.ExtractError(
                            "cannot read {!r}".format(member.name))
                    with source, os.fdopen(file_fd, "wb", closefd=False) as output:
                        shutil.copyfileobj(source, output)
                    os.fchmod(file_fd, member.mode & 0o777)
                finally:
                    os.close(file_fd)
            finally:
                os.close(directory_fd)
    finally:
        os.close(root_fd)


def main():
    if len(sys.argv) != 2:
        print("usage: unpack ARCHIVE", file=sys.stderr)
        return 2

    base = os.path.realpath(os.path.join(os.path.dirname(__file__), os.pardir))
    destination = os.path.join(base, "incoming")
    try:
        with tarfile.open(sys.argv[1], mode="r:*") as archive:
            members = checked_members(archive)
            preflight_destination(destination, members)
            extract_checked(archive, destination, members)
    except (OSError, tarfile.TarError, ValueError) as error:
        print("unpack: rejected: {}".format(error), file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
PYEOF
